// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 ts1, uint256 ts2) public {
        vm.assume(actor != address(0) && actor != address(this));
        uint256 diff = block.difficulty;
        uint256 r1 = uint256(keccak256(abi.encodePacked(ts1, diff, actor))) % 2;
        uint256 r2 = uint256(keccak256(abi.encodePacked(ts2, diff, actor))) % 2;
        // admissible domain: both plays lose, so the win-branch ETH transfers never run
        vm.assume(r1 == 1 && r2 == 1);

        vm.deal(actor, 20);
        vm.warp(ts1);
        vm.prank(actor);
        c.play{value: 10}();
        vm.warp(ts2);
        vm.prank(actor);
        c.play{value: 10}();

        assertTrue(c.pot() == 20);
    }
}
